import {
    Form,
    Modal,
    Upload,
    Button,
    Icon,
    notification,
  } from "antd";
  import React, { useState, useEffect } from "react";
  import { connect } from "react-redux";
  import { getFormItems } from "./getFormItems";
  import policyActions from "../../../../redux/policy/actions";
  import tapInsureActions from "../../../../../src/PasarApp/redux/tapInsure/actions";
  import { isEqual, size } from "lodash";
  const { confirm } = Modal;
  
  const { uploadPolicyFile, resetReduxState: policyResetReduxState } =
    policyActions;
  const { addUpdateReport } = tapInsureActions;
  
  const EditForm = (props) => {
    const {
      form,
      editFormRef,
      fieldName,
      inputEditable,
      onCancel,
      formData = null,
      userData,
      uploadPolicyFile,
      uploadPolicyFileStatus,
      uploadPolicyFileData,
      policyResetReduxState,
      addUpdateReport,
    } = props;
  
    const { setFieldsValue, getFieldsValue, validateFields } = form;
  
    const [uploading, setUploading] = useState(false);
    const [fileUrl, setFileUrl] = useState(null);
    const [filename, setFilename] = useState(null);
    const [formBody, setFormBody] = useState({});
    const [documentUrls, setDocumentUrls] = useState([]);
  
    const allowedExtensions = ["xls", "xlsx"];
  
    useEffect(() => {
      if (formData) {
        const fields = {
          ...formData,
          document: formData.document ? [formData.document] : [],
          is_active: formData.is_active ? "True" : "False",
        };
        setFieldsValue(fields);
  
        if (formData.document) {
          setFileUrl(formData.document);
          setFilename(formData.document.split("/").pop());
          setDocumentUrls([{ url: formData.document }]);
        }
      }
    }, [formData]);
  
    useEffect(() => {
      if (uploadPolicyFileStatus === "success" && uploadPolicyFileData?.url) {
        const newUrl = uploadPolicyFileData.url;
        const fileName = newUrl.split("/").pop();
        setFileUrl(newUrl);
        setFilename(fileName);
        setDocumentUrls([{ url: newUrl }]);
        setFieldsValue({ document: [newUrl] });
        setUploading(false);
        policyResetReduxState(["uploadPolicyFileStatus", "uploadPolicyFileData"]);
      }
    }, [uploadPolicyFileStatus]);
  
    const checkFileExtension = (filename) => {
      const fileExtension = filename.split(".").pop().toLowerCase();
      return allowedExtensions.includes(fileExtension);
    };
  
    const handleUploadChange = async (info) => {
      const file = info?.file?.originFileObj;
  
      if (!file) return;
  
      if (!checkFileExtension(file.name)) {
        notification.error({ message: "Invalid file type (.xls, .xlsx only)" });
        return;
      }
      try {
        const formData = new FormData();
  
        let originalName = file.name.split(".")[0];
        let cleanedName = originalName.replace(/\s+/g, "").replace(/[^a-zA-Z0-9]/g, "_");
  
        formData.append("file", file);
        formData.append("path", `publication/${cleanedName}_${Date.now()}`);
        formData.append("identifier", "b2c");
  
        uploadPolicyFile({ body: formData });
        setUploading(true);
      } catch (err) {
        notification.error({ message: "Upload failed" });
        setUploading(false);
      }
    };
  
    const handleRemoveFile = () => {
      setFileUrl(null);
      setFilename(null);
      setDocumentUrls([]);
      setFieldsValue({ document: [] });
    };
  
    const validateForm = () => {
      return new Promise((resolve) => {
        validateFields((err) => {
          if (err) {
            notification.error({ message: "Please fix form errors." });
            resolve(false);
          } else {
            resolve(true);
          }
        });
      });
    };
  
    const submitHandler = async (e) => {
      e.preventDefault();
  
      const isValid = await validateForm();
      if (!isValid) return;
  
      const currentFormData = getFieldsValue();
  
      if (size(formBody) > 0 && isEqual(formBody, currentFormData)) {
        console.log("No changes in form");
        return;
      }
  
      const docUrl = documentUrls.map((doc) => doc.url).join(",");
  
      const payload = {
        title: currentFormData.name,
        link: docUrl,
        created_by: userData?.email,
        is_active: true,
        category: 'workshop-data'
      };
  
      setFormBody(payload);
      addUpdateReport(payload);
    };

    const showConfirmBeforeSubmit = (e) => {
      e.preventDefault();
    
      confirm({
        title: "Are you sure you want to submit?",
        onOk() {
          return submitHandler(e);
        },
      });
    };
  
    return (
      <Modal
        visible={!inputEditable}
        title={formData ? "Edit Report" : "Add Report"}
        okText="Submit"
        cancelText="Cancel"
        onCancel={onCancel}
        onOk={showConfirmBeforeSubmit}
        destroyOnClose
      >
        <div>
          <Form ref={editFormRef}>
            {getFormItems(
              {
                fieldName: "name",
                type: { type: "string" },
                label: "Name",
                initialValue: formData?.name || "",
                required: true,
              },
              form
            )}
  
            <Form.Item label={<b style={{ fontSize: "12px" }}>Upload Document</b>}>
              {form.getFieldDecorator("document", {
                initialValue: formData?.document ? [formData.document] : [],
                rules: [{ required: true, message: "Please upload a document" }],
              })(
                <>
                  <Upload
                    name="documents"
                    showUploadList={false}
                    multiple={false}
                    customRequest={({ onSuccess }) =>
                      setTimeout(() => onSuccess("ok"), 0)
                    }
                    onChange={handleUploadChange}
                  >
                    <div style={{display: 'flex', flexDirection: 'column', gap: '6px'}}>
                      <Button disabled={uploading}>
                        <Icon type="upload" /> {uploading ? "Uploading..." : "Upload"}
                      </Button>
                      <b style={{fontSize: '10px', color: 'red'}}>* xls, xlsx only</b>
                    </div>
                  </Upload>
  
                  {fileUrl && (
                    <div style={{ marginTop: 10 }}>
                      <div
                        style={{
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "space-between",
                          marginBottom: 6,
                        }}
                      >
                        <span>
                          <Icon type="file" style={{ marginRight: 8 }} />
                          {filename}
                        </span>
                        <Icon
                          type="delete"
                          style={{ color: "red", cursor: "pointer" }}
                          onClick={handleRemoveFile}
                        />
                      </div>
                    </div>
                  )}
                </>
              )}
            </Form.Item>
          </Form>
        </div>
      </Modal>
    );
  };
  
  const WrappedEditForm = Form.create()(EditForm);
  
  export default connect(
    (state) => ({
      userData: state.Auth.profile,
      uploadPolicyFileStatus: state.Insurance.uploadPolicyFileStatus,
      uploadPolicyFileData: state.Insurance.uploadPolicyFileData,
    }),
    {
      uploadPolicyFile,
      policyResetReduxState,
      addUpdateReport,
    }
  )(WrappedEditForm);
  