import {
  Button,
  Card,
  Col,
  Icon,
  notification,
  Row,
  Spin,
  Table,
  Tag,
} from "antd";
import { LayoutWrapper } from "./index.style";
import { useCallback, useEffect, useState } from "react";
import WrappedEditForm from "./components/addEditWorkshopLIst";
import { connect } from "react-redux";
import financialActions from "../../../PasarApp/redux/tapInsure/actions";
import moment from "moment-timezone";
import { useLocation, useHistory } from "react-router";
import QuerySearchBuilder from "../../../helpers/querySearchBuilder";
import { FilterInput } from "../../../components/tables/helperCells";
import PermissionChecker from "../../../components/permissionChecker";

const { getWorkshopList, resetReportingConfigRedux } = financialActions;
const DUMMY_TEMPLATE_URL =
  "https://storage.googleapis.com/consumer-testing/Reports/Workshop%20Data%20Template.xlsx";

const WorkshopList = (props) => {
  const [openEditForm, setOpenEditForm] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const [searchTextQuery, setSearchTextQuery] = useState({});
  const [isChange, setIsChange] = useState(false);
  const [isFilterVisible, setIsFilterVisible] = useState("");
  const [filters, setFilters] = useState({});

  const {
    getWorkshopList,
    workshopList = [],
    tableDataSourceLoading,
    addUpdateMessage,
    resetReportingConfigRedux,
    permissions,
  } = props;

  const location = useLocation();
  const history = useHistory();

  const searchParams = new URLSearchParams(location.search);
  const defaultPage = parseInt(searchParams.get("page") || "1", 10);

  useEffect(() => {
    setCurrentPage(defaultPage);
    getWorkshopList({
      category: "workshop-data",
      page: defaultPage,
      offset: (defaultPage - 1) * 15,
      limit: 15,
      ordering: '-updated_at',
    });
  }, [location.search]);

  const handlePageChange = (pagination) => {
    const newPage = pagination.current;
    setCurrentPage(newPage);
    const search = QuerySearchBuilder({ page: newPage });
    history.push({ pathname: location.pathname, search });
  };

  useEffect(() => {
    if (addUpdateMessage) {
      notification[addUpdateMessage === "success" ? "success" : "error"]({
        message:
          addUpdateMessage === "success"
            ? "Workshop Data Updated Successfully!"
            : "Error Occurred!",
      });
      resetReportingConfigRedux(["addUpdateMessage"]);
      setOpenEditForm(false);
      const page = parseInt(
        new URLSearchParams(location.search).get("page") || "1",
        10
      );
      getWorkshopList({
        category: "workshop-data",
        page,
        offset: (page - 1) * 15,
        limit: 15,
        ordering: '-updated_at',
      });
    }
  }, [addUpdateMessage]);

  useEffect(() => {
    return () => {
      resetReportingConfigRedux([
        "addUpdateMessage",
        "workshopList",
        "workshoplListMessage",
      ]);
    };
  }, []);

  const handleClose = () => {
    setOpenEditForm(false);
  };

  const handleOpen = () => {
    setOpenEditForm(true);
  };

  const handleDownload = (url) => {
    if (url) {
      window.open(url, "_blank");
    }
  };

  const handleInputChange = useCallback(
    (event, identifier) => {
      setSearchTextQuery({
        ...searchTextQuery,
        [identifier]: event.target.value,
      });
      setIsChange(true);
    },
    [searchTextQuery]
  );

  const handleSearch = (e) => {
    e.preventDefault();
    setIsFilterVisible("");
    setFilters(searchTextQuery);
    getWorkshopList({
      category: "workshop-data",
      page: defaultPage,
      offset: (defaultPage - 1) * 15,
      limit: 15,
      ordering: '-updated_at',
      ...searchTextQuery,
    });
  };

  const handleResetFilter = (key) => {
    const updatedQuery = { ...searchTextQuery };
    delete updatedQuery[key];

    setSearchTextQuery(updatedQuery);
    setIsChange(true);
    setIsFilterVisible("");
    setFilters(updatedQuery);

    const search = QuerySearchBuilder({ ...updatedQuery });
    history.push({ pathname: location.pathname, search });
    getWorkshopList({
      category: "workshop-data",
      page: defaultPage,
      offset: (defaultPage - 1) * 15,
      limit: 15,
      ordering: '-updated_at',
      ...updatedQuery,
    });
  };

  const columns = [
    {
      key: "actions",
      title: "Actions",
      render: (_, record) => (
        <div style={{ display: "flex", gap: "20px", justifyContent: "center" }}>
          <Icon
            type="download"
            style={{ color: "#1890ff", cursor: "pointer", fontSize: 20 }}
            onClick={() => handleDownload(record?.link)}
          />
        </div>
      ),
    },
    {
      key: "title",
      title: "Name",
      dataIndex: "title",
      render: (data) => data || "-",
      filterDropdown: (
        <div style={{ padding: 8 }}>
          <FilterInput
            idIdentifier="title"
            className=""
            searchText={isChange ? searchTextQuery.name : ""}
            onInputChange={(e) => handleInputChange(e, "name")}
            onSearch={(e) => handleSearch(e, "name")}
          />
          <Button
            size="small"
            style={{ marginTop: 8, width: "100%" }}
            onClick={() => handleResetFilter("name")}
          >
            Reset
          </Button>
        </div>
      ),
      filterDropdownVisible: isFilterVisible === "title",
      onFilterDropdownVisibleChange: (visible) =>
        setIsFilterVisible(visible ? "title" : searchTextQuery.title),
    },
    {
      key: "created_at",
      title: "Created At",
      dataIndex: "created_at",
      render: (data) => (data ? moment(data).format("YYYY-MM-DD HH:mm") : "-"),
    },
    {
      key: "updated_at",
      title: "Updated At",
      dataIndex: "updated_at",
      render: (data) => (data ? moment(data).format("YYYY-MM-DD HH:mm") : "-"),
    },
    {
      key: "created_by",
      title: "User",
      dataIndex: "created_by",
      render: (data) => data || "-",
    },
    {
      key: "status",
      title: "Status",
      render: (_, record) => {
        const status = record?.extra_data?.status;
        return status ? <>{status.toUpperCase()}</> : <b>-</b>;
      },
    },
  ];

  const removeFilter = (filterKeyToBeRemoved) => {
    const updatedQuery = searchTextQuery;

    delete updatedQuery[filterKeyToBeRemoved];

    setSearchTextQuery(updatedQuery);
    const searchQuery = QuerySearchBuilder(updatedQuery);
    history.push({ pathname: location.pathname, search: searchQuery });
    getWorkshopList({
      category: "workshop-data",
      page: defaultPage,
      offset: defaultPage * 15,
      limit: 15,
      ordering: '-updated_at',
      ...updatedQuery,
    });
  };

  const getFilterTag = (filters, key) => {
    return Object.keys(filters).map((key, value) => (
      <Tag
        className="top-filter"
        key={key}
        color="purple"
        closable="closable"
        onClose={() => removeFilter(key)}
      >
        {key}: {filters[key]}
      </Tag>
    ));
  };

  return (
    <LayoutWrapper>
      <Card>
        <Row type="flex" justify="space-between">
          <Col>
            <h1 className="label-name">
              <b>Workshop Data: {workshopList?.metadata?.count || 0}</b>
            </h1>
            {getFilterTag(filters)}
          </Col>
          <Col>
            <div
              className="button__section"
              style={{ display: "flex", gap: "10px" }}
            >
              <Button>
                <a
                  href={DUMMY_TEMPLATE_URL}
                  download
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  Download Template
                </a>
              </Button>
              <PermissionChecker
                permissionSetter="ops.tapinsure-add-workshop-data"
                permissionGetter={permissions}
              >
                <Button type="primary" onClick={handleOpen}>
                  <b>+ Add Workshop File</b>
                </Button>
              </PermissionChecker>
            </div>
          </Col>
        </Row>

        <div className="table-container">
          <Spin
            spinning={tableDataSourceLoading}
            tip="Reporting List Loading ..."
          >
            <Table
              bordered
              columns={columns}
              dataSource={workshopList.results}
              rowKey={(record) => record.id}
              pagination={{
                pageSize: 15,
                current: currentPage,
                total: workshopList?.metadata?.count || 0,
              }}
              onChange={handlePageChange}
            />
          </Spin>
        </div>
      </Card>

      {openEditForm && <WrappedEditForm onCancel={handleClose} />}
    </LayoutWrapper>
  );
};

export default connect(
  (state) => ({
    workshopList: state.TapInsureConfigurable.workshopList,
    workshoplListMessage: state.TapInsureConfigurable.workshoplListMessage,
    tableDataSourceLoading: state.Loading.GET_WORKSHOP_REPORTS,
    addUpdateData: state.TapInsureConfigurable.addUpdateData,
    addUpdateMessage: state.TapInsureConfigurable.addUpdateMessage,
  }),
  {
    getWorkshopList,
    resetReportingConfigRedux,
  }
)(WorkshopList);
